// src/Routes.js
import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Navbar from './components/Navbar';
import Home from './pages/Home';
import Discussion from './pages/Discussion';
import CommunityOption1 from './pages/CommunityOption1';
import CommunityOption2 from './pages/CommunityOption2';
import Plans from './pages/Plans';
import Login from './pages/Login';
import SignUp from './pages/SignUp';

const AppRoutes = () => {
  return (
    <Router>
      <Navbar />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/discussion" element={<Discussion />} />
        <Route path="/community/option1" element={<CommunityOption1 />} />
        <Route path="/community/option2" element={<CommunityOption2 />} />
        <Route path="/plans" element={<Plans />} />
        <Route path="/login" element={<Login />} />
        <Route path="/signup" element={<SignUp />} />
      </Routes>
    </Router>
  );
};

export default AppRoutes;
